import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Image aspect ratio: 512/320 = 1.6
  const width = 1.6;
  const height = 1.0;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';
  const texture = ctx.textureLoader.load(imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material for static composition
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position, rotation, and scale
  const pos = config.scenePosition || {};
  group.position.set(pos.x || 0, pos.y || 0, pos.z || 0);

  if (pos.rotationXYZ) {
    const [rx, ry, rz] = pos.rotationXYZ;
    group.rotation.set(rx, ry, rz);
  }

  if (pos.scaleXYZ) {
    const [sx, sy, sz] = pos.scaleXYZ;
    group.scale.set(sx, sy, sz);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Event handlers (empty for this static card)
  group.userData.handlers = {};

  return group;
}
